<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/functions.php';require_permission($pdo,'view_orders');$active='orders';$pageTitle='Orders';
$status=$_GET['status']??'';$sql="SELECT o.*,u.name client_name,e_u.name employee_name FROM orders o JOIN clients c ON c.id=o.client_id JOIN users u ON u.id=c.user_id LEFT JOIN employees e ON e.id=o.employee_id LEFT JOIN users e_u ON e_u.id=e.user_id";$params=[];if(in_array($status,['pending','confirmed','processing','shipped','delivered','cancelled'],true)){$sql.=" WHERE o.status=?";$params[]=$status;}$sql.=" ORDER BY o.id DESC";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();include __DIR__.'/../../includes/header.php';?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><span class="eyebrow">OPERATIONS</span><h1 class="page-title">Orders</h1></div><div class="d-flex gap-2"><a class="btn btn-stare" href="create.php"><i class="bi bi-plus-lg"></i> New Order</a><form><select class="form-select" name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['pending','confirmed','processing','shipped','delivered','cancelled'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></form></div></div>
<div class="panel"><div class="table-responsive"><table class="table stare-table align-middle"><thead><tr><th>Order</th><th>Client</th><th>Employee</th><th>Total</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $o):?><tr><td><strong>#<?=e($o['order_number'])?></strong></td><td><?=e($o['client_name'])?></td><td><?=e($o['employee_name']??'Unassigned')?></td><td><?=money($o['total_amount'])?></td><td><?=status_badge($o['status'])?></td><td><?=e(date('Y-m-d H:i',strtotime($o['created_at'])))?></td><td><a class="action-link" href="view.php?id=<?=$o['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../../includes/footer.php';?>
